WITH ins AS (
  INSERT INTO activity_conflicts (project_id, activity_id, conflict_number, title, theme, severity, side_a, side_b, why, solutions, sort_order)
  SELECT p.id, a.id, ci.conflict_number, ci.title, ci.theme, ci.severity, ci.side_a, ci.side_b, ci.why, ci.solutions, ci.sort
  FROM conflict_import ci
  JOIN projects p ON p.name = 'Sjabloon – Stakeholders per fase' AND p.deleted_at IS NULL
  JOIN phases f ON f.project_id = p.id AND f.name = ci.phase_name AND f.deleted_at IS NULL
  JOIN activities a ON a.phase_id = f.id AND a.number = ci.activity_number AND a.deleted_at IS NULL
  WHERE NOT EXISTS (
    SELECT 1 FROM activity_conflicts k
    WHERE k.activity_id = a.id AND k.deleted_at IS NULL
      AND (k.conflict_number = ci.conflict_number OR (ci.conflict_number IS NULL AND k.title = ci.title))
  )
  RETURNING *
)
INSERT INTO history_events (project_id, entity_type, entity_id, op, before, after, actor_id, batch_id, note)
SELECT ins.project_id, 'activity_conflict', ins.id, 'create', NULL, jsonb_build_object(
    'id', ins.id, 'projectId', ins.project_id, 'activityId', ins.activity_id, 'conflictNumber', ins.conflict_number,
    'title', ins.title, 'theme', ins.theme, 'severity', ins.severity, 'sideA', ins.side_a, 'sideB', ins.side_b,
    'why', ins.why, 'solutions', ins.solutions, 'sortOrder', ins.sort_order,
    'version', ins.version, 'deletedAt', CASE WHEN ins.deleted_at IS NULL THEN NULL ELSE to_char(ins.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN ins.created_at IS NULL THEN NULL ELSE to_char(ins.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN ins.updated_at IS NULL THEN NULL ELSE to_char(ins.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END),
       c.actor_id, c.batch_id, 'Belangenconflicten per activiteit uit Excel: Belangenverstrengeling_per_fase_woningbouw.xlsx'
FROM ins CROSS JOIN import_ctx c;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM conflict_import ci
  WHERE NOT EXISTS (
    SELECT 1 FROM activities a
    JOIN phases f ON f.id = a.phase_id AND f.deleted_at IS NULL
    JOIN projects p ON p.id = f.project_id AND p.name = 'Sjabloon – Stakeholders per fase' AND p.deleted_at IS NULL
    WHERE a.number = ci.activity_number AND f.name = ci.phase_name AND a.deleted_at IS NULL
  );
  IF n > 0 THEN RAISE NOTICE '% conflictregels hadden geen bijpassende activiteit en zijn overgeslagen.', n; END IF;
END $$;

COMMIT;
